import * as React from "react";
import { Check, ChevronDown, MoreHorizontal, Plus, RefreshCw, Upload } from "lucide-react";
import { cn } from "@/lib/utils";
import { ToggleGroup, ToggleGroupItem } from "@/components/ui/toggle-group";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogClose,
  DialogContent,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip";
import { suggestViewName } from "./filterMemory";

/**
 * Preset-view row.
 *
 * The interaction is the DS's finalized one, from the Data Action Control unit
 * (`data-action-control/DataActionControl.tsx`, rows 177–228) — NOT the
 * `PresetTabs` helper in `experiments/dac-rebuild`, which is archived
 * (`arc-rebuild-*` in App.tsx's ARCHIVE_KEYS) and only stubs view creation by
 * appending "View 1", "View 2" with no name and no state.
 *
 * What that means concretely:
 *   • "Default" is a reset control, not a tab — it restores the default state.
 *   • Creating a view opens a Dialog and the view is NAMED. A view captures the
 *     current search / sort / hidden columns / page size / delivery date, and
 *     selecting it restores them. A view that carries no state is just a label.
 *   • Each saved view has a `⋯` menu revealed on hover: Update view (only when
 *     the current state has drifted), Rename, Delete.
 *   • A brand dot next to the active tab marks unsaved drift.
 *   • Tabs are plain buttons with a `border-b-2` active underline — not the
 *     shadcn Tabs component, so the `⋯` control can sit inside the tab.
 */

/** The slice of screen state a saved view captures and restores. */
export interface ViewState {
  search: string;
  sortKey: string | null;
  sortDir: "asc" | "desc" | null;
  hidden: string[];
  /**
   * Column order as keys, outermost left. Part of the view because which two
   * columns sit side by side IS the view for anyone comparing them — a view
   * that restored the filters but not the arrangement would rebuild half the
   * thing. Empty means "as the table declares them".
   */
  columnOrder: string[];
  /** Reader-set column widths in px, by key. Empty means "as declared". */
  columnWidths: Record<string, number>;
  pageSize: number;
  /** Delivery date as `YYYY-MM-DD` — views are date-scoped like everything else. */
  dateKey: string;
  /** Which column the "Search by column" tool is pointed at. */
  colScope: string;
  /** Its query. Captured so a saved view restores the narrowing it was built with. */
  colQuery: string;
  /**
   * Active grouping dimensions, outermost first. ORDER IS SIGNIFICANT and is
   * compared as given — Status › Customer and Customer › Status are different
   * views, not the same one.
   */
  groupBy: string[];
}

export interface SavedView {
  id: string;
  name: string;
  state: ViewState;
}

/** Order-independent comparison, so drift detection can't be fooled by key order. */
export function viewStateKey(s: ViewState): string {
  return JSON.stringify({
    search: s.search,
    sortKey: s.sortKey,
    sortDir: s.sortDir,
    hidden: [...s.hidden].sort(),
    pageSize: s.pageSize,
    dateKey: s.dateKey,
    colScope: s.colScope,
    colQuery: s.colQuery,
    // Not sorted: the order of the dimensions is part of the state.
    groupBy: s.groupBy ?? [],
  });
}

export interface FuelOrdersViewBarProps {
  /**
   * Only the id and name are read here — the captured state is opaque to this
   * component, which is why Asset Orders and Customers can reuse the row with
   * their own state shapes.
   */
  views: { id: string; name: string }[];
  /**
   * BUILT-IN VIEWS, sitting FIRST, ruled off from Default and the saved ones.
   *
   * A saved view is something a reader MADE; a preset is something the business
   * already is. The businesses inside a line of service — fuel's transport and
   * tank wagon — are the second kind: a broker works one of them, all day, and
   * would otherwise rebuild the same filter every morning and save it under the
   * name it already has.
   *
   * They carry no `⋯` menu, because there is nothing to rename, update or
   * delete about a fact. Picking one is picking Default AND that narrowing, so
   * the two selections are one control and only one tab is ever underlined —
   * and picking one from inside a saved view drops that view.
   */
  presets?: { key: string; label: string }[];
  /** `null` = no preset; the Default tab owns the underline. */
  presetKey?: string | null;
  /** `null` clears the preset — the row sends it when a view takes over. */
  onPresetChange?: (key: string | null) => void;
  /** `null` = the Default view is active. */
  activeId: string | null;
  /** Current state differs from the active view (or from default). */
  dirty: boolean;
  onApply: (id: string) => void;
  onResetToDefault: () => void;
  onCreate: (name: string) => void;
  onRename: (id: string, name: string) => void;
  onUpdate: (id: string) => void;
  onDelete: (id: string) => void;
  /**
   * A segmented scope control, seated at the right of this row ahead of the
   * actions. For a list that holds two KINDS of record rather than two filters
   * of one — fuel orders and asset orders take different forms and answer
   * different questions, so which of them you are looking at is a decision made
   * before anything else on the row applies.
   */
  segments?: { key: string; label: string }[];
  segmentValue?: string;
  onSegmentChange?: (key: string) => void;
  /** Primary CTA — rendered at the right end of this row. */
  onCreateOrder?: () => void;
  /**
   * Turns the CTA into a menu. A list whose Create means several DIFFERENT
   * records — a delivery, an asset out, an asset back — cannot express that in
   * one button: the three take different forms, so the choice has to be made
   * before the form opens rather than by a Type field inside it.
   *
   * Each option carries a `detail` because the names alone do not separate
   * them: "Asset Delivery" and "Asset Pickup" are one word apart and opposite.
   */
  createMenu?: {
    key: string;
    label: string;
    /** Optional — Sales' menu carries names only (Pavan, 2026-10-07). */
    detail?: string;
    /**
     * Turns the entry into a GROUP: its label and detail stop being a button
     * and become the heading over a radio list. Use it where one kind of thing
     * comes in two named variants — the variant is a property of the thing, not
     * a third kind, and a flat menu of near-identical names is where a one-word
     * difference gets misread.
     *
     * Choosing an entry ACTS in one click: `onCreateSelect` gets the
     * chosen key. Each entry starts its order; nothing is held selected.
     */
    choices?: { key: string; label: string; detail?: string }[];
  }[];
  onCreateSelect?: (key: string) => void;
  /** CTA label. Defaults to Fuel Orders' own verb. */
  ctaLabel?: string;
  /** Export — sits immediately left of the CTA. */
  onExport?: () => void;
}

const tabCls = (isActive: boolean) =>
  cn(
    /* `self-end` IS THE WHOLE POINT OF THE ACTIVE RULE. The row is
       `items-center` and its height is set by the taller right cluster, so a
       centred tab floated a couple of pixels clear of the hairline and its 2px
       underline read as a second, parallel line. Bottom-aligned, the two meet:
       the tab's rule lands on the divider with nothing between them. */
    "self-end px-3 py-2 text-xs whitespace-nowrap outline-none transition-colors focus-visible:ring-2 focus-visible:ring-ring/50",
    isActive
      ? "font-medium text-foreground"
      : "text-muted-foreground hover:text-foreground"
  );

/** Brand dot marking unsaved drift on the active tab. */
function DirtyDot() {
  return (
    <span
      className="ml-1.5 inline-block size-1.5 rounded-full bg-brand align-middle"
      aria-label="unsaved changes"
    />
  );
}

export function FuelOrdersViewBar({
  views,
  activeId,
  dirty,
  onApply,
  onResetToDefault,
  presets,
  presetKey = null,
  onPresetChange,
  onCreate,
  onRename,
  onUpdate,
  onDelete,
  segments,
  segmentValue,
  onSegmentChange,
  onCreateOrder,
  createMenu,
  onCreateSelect,
  onExport,
  ctaLabel = "Create Order",
}: FuelOrdersViewBarProps) {
  const [dialog, setDialog] = React.useState<{
    mode: "new" | "rename";
    id?: string;
    name: string;
    /** A NEW VIEW'S SUGGESTED NAME, from the filters on (Pavan, 2026-10-21) —
        the placeholder; → or Tab takes it to type on from, and Save with
        the box empty saves it. */
    suggestion?: string;
  } | null>(null);


  const submit = () => {
    if (!dialog) return;
    const name = dialog.name.trim() || (dialog.mode === "new" ? dialog.suggestion ?? "" : "");
    if (!name) return;
    /* Creating activates the new view, so it clears the business for the same
       reason applying one does. */
    if (dialog.mode === "new") {
      onPresetChange?.(null);
      onCreate(name);
    }
    else if (dialog.id) onRename(dialog.id, name);
    setDialog(null);
  };

  return (
    <>
      {/* -mx-4 -mt-4 cancels the content layer's 16px inset so the hairline spans
          the full panel width, as it does on the DS screen. */}
      {/* NO BOTTOM PADDING. The active tab's 2px rule has to LAND ON the row's
          hairline — that is what makes it read as a tab and not as an underline
          floating above a line. The row used to keep 2px under the tabs, which
          left a hairline gap between the two rules and made the whole tab strip
          look one notch high. Everything on the right measures its own distance
          from the divider with `self-end` + a margin, so those margins carry
          the 2px that came out of here. */}
      <div className="-mx-4 -mt-4 flex shrink-0 items-center gap-1 border-b border-border px-3 pt-0.5">
        {/* THE BUSINESSES COME FIRST, then a rule, then the views.

            They are two different kinds of thing and the row was reading as one
            list of six. A preset is WHICH BUSINESS this is — a fact about the
            work, true before anyone opened the screen; a view is a narrowing
            somebody MADE and can rename or delete. Ordering the facts first and
            ruling them off says which half of the row you are in, and puts the
            thing a broker changes least often where it is easiest to find.

            DEFAULT IS STILL THE RESTING STATE — it holds the underline when no
            business and no view is on, and it is the first thing after the
            rule, which is where the reader's eye lands once they are past the
            facts. */}
        {presets?.map((p) => (
          <button
            key={p.key}
            type="button"
            /* A PRESET IS DEFAULT PLUS A NARROWING, so picking one from inside
               a saved view drops the view as well. The row used to hide the
               presets while a view was active rather than answer this; hidden
               controls are a worse answer than a stated rule. */
            onClick={() => {
              if (activeId !== null) onResetToDefault();
              onPresetChange?.(p.key);
            }}
            className={cn(
              tabCls(presetKey === p.key),
              "border-b-2",
              presetKey === p.key ? "border-foreground" : "border-transparent"
            )}
          >
            {p.label}
          </button>
        ))}

        {presets && presets.length > 0 && (
          <span aria-hidden className="mx-2 mb-2 h-5 w-px shrink-0 self-end bg-border" />
        )}

        <button
          type="button"
          onClick={onResetToDefault}
          className={cn(
            tabCls(activeId === null && presetKey === null),
            "border-b-2",
            activeId === null && presetKey === null
              ? "border-foreground"
              : "border-transparent"
          )}
        >
          All
          {activeId === null && presetKey === null && dirty && <DirtyDot />}
        </button>

        {views.map((v) => {
          const isActive = v.id === activeId;
          return (
            /* The wrapper is the flex child, so the alignment lives here —
               `tabCls`'s own `self-end` cannot reach past it. */
            <div key={v.id} className="group/tab flex items-end self-end pr-1">
              <button
                type="button"
                /* A VIEW AND A BUSINESS ARE MUTUALLY EXCLUSIVE, because only
                   one tab in this row can hold the underline and a narrowing
                   nobody can see is the thing Default exists to prevent. A
                   saved view does not capture the business — `ViewState` has no
                   field for it — so taking a view means leaving the business,
                   the same way picking a business leaves the view. */
                onClick={() => {
                  onPresetChange?.(null);
                  onApply(v.id);
                }}
                className={cn(
                  tabCls(isActive),
                  "border-b-2",
                  isActive ? "border-foreground" : "border-transparent"
                )}
              >
                {v.name}
              </button>
              {/* CHANGED SINCE SAVED — THE UPDATE IS ONE PRESS, beside the
                  name (Pavan, 2026-10-21), not a dot that sends you to ⋯.
                  The two-arrow refresh glyph, in grey (2026-10-22). */}
              {isActive && dirty && (
                <Tooltip>
                  <TooltipTrigger asChild>
                    <button
                      type="button"
                      aria-label={`Update ${v.name} with the changes`}
                      onClick={() => onUpdate(v.id)}
                      className="mb-1.5 ml-0.5 inline-flex size-6 items-center justify-center rounded-md text-muted-foreground outline-none transition-colors hover:bg-accent hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/50"
                    >
                      <RefreshCw className="size-3.5" />
                    </button>
                  </TooltipTrigger>
                  <TooltipContent>Update changes</TooltipContent>
                </Tooltip>
              )}
              <DropdownMenu>
                <DropdownMenuTrigger asChild>
                  <button
                    type="button"
                    aria-label={`${v.name} options`}
                    className="ml-0.5 rounded p-0.5 text-muted-foreground opacity-0 outline-none transition-opacity hover:text-foreground focus-visible:opacity-100 group-hover/tab:opacity-100 data-[state=open]:opacity-100"
                  >
                    <MoreHorizontal className="size-3.5" />
                  </button>
                </DropdownMenuTrigger>
                <DropdownMenuContent align="start">
                  {isActive && dirty && (
                    <DropdownMenuItem onClick={() => onUpdate(v.id)}>
                      <Check /> Update view
                    </DropdownMenuItem>
                  )}
                  <DropdownMenuItem
                    onClick={() =>
                      setDialog({ mode: "rename", id: v.id, name: v.name })
                    }
                  >
                    Rename
                  </DropdownMenuItem>
                  <DropdownMenuItem
                    variant="destructive"
                    onClick={() => onDelete(v.id)}
                  >
                    Delete
                  </DropdownMenuItem>
                </DropdownMenuContent>
              </DropdownMenu>
            </div>
          );
        })}

        <button
          type="button"
          onClick={() => setDialog({ mode: "new", name: "", suggestion: suggestViewName() })}
          /* Not a tab — it has no rule to land, so it keeps 4px off the
             hairline rather than sitting on it. */
          className="mb-1 ml-1 inline-flex items-center gap-1 self-end rounded-md px-2 py-1 text-xs text-muted-foreground outline-none transition-colors hover:bg-accent hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/50"
        >
          <Plus className="size-4" /> View
        </button>

        {/*
          Primary CTA, moved up here from the toolbar's right cluster so it sits
          on the preset-view row.

          `size="xs"` — the DS step below `sm` (h-6/24px vs h-8/32px). This row
          carries text tabs, not controls, so the 32px button sat heavy on it.

          `rounded-[4px]` is OFF the DS radius scale, which runs
          xs 2px / sm 6px / md 8px / lg 10px — there is no 4px step. Asked for
          directly, so it stands as a literal, but it is the one raw value in
          this file. FOLLOW-UP: either add a 4px step to the radius scale in
          src/index.css and swap this for the token, or move the button to
          `rounded-sm` (6px). A decision to make here, not a Figma round-trip.

          `mr-1` is load-bearing: this row cancels the content layer's 16px inset
          with -mx-4 and re-pads at px-3 (12px) so its hairline spans the whole
          panel, which would leave the button 4px further right than the toolbar
          controls below it. The extra 4px puts both right edges on the same line.

          `self-end mb-3` sets the gap to the hairline. The row is
          `items-center`, so the button opts out of centring and measures from the
          bottom instead; 12px of margin puts exactly 12px between the button's
          lower edge and the divider. (It was 10 + the row's own 2px of bottom
          padding, until the tabs took that padding away so their rule could land
          on the hairline.)
        */}
        {/* THE SCOPE, THEN SPACE, THEN THE ACTIONS. The segments choose WHICH
            list this is; the buttons act on it. A 20px gap says they are not
            the same kind of control (a rule did, until 2026-10-05). It takes the `ml-auto` so the whole right cluster sits
            right; the CTA below no longer needs it. */}
        {segments && segments.length > 0 && (
          <>
            <ToggleGroup
              type="single"
              variant="outline"
              size="sm"
              value={segmentValue}
              /* Radix emits "" when the active item is pressed again. A scope is
                 never empty — ignore the deselect so one segment stays chosen. */
              onValueChange={(next) => next && onSegmentChange?.(next)}
              aria-label="Order kind"
              className="mb-2.5 ml-auto h-7 self-end"
            >
              {segments.map((seg) => (
                <ToggleGroupItem
                  key={seg.key}
                  value={seg.key}
                  className="h-7 px-2.5 text-xs font-normal data-[state=on]:font-medium"
                >
                  {seg.label}
                </ToggleGroupItem>
              ))}
            </ToggleGroup>
            {/* SPACE, NOT A RULE (Pavan, 2026-10-05): 12px here plus the
                row's 4px gap each side — 20px between the scope and the CTA. */}
            <span aria-hidden className="w-3 shrink-0" />
          </>
        )}

        {/* NO HANDLER, NO BUTTON. A list without a create flow — Vendors, where
            a carrier is onboarded through a contract rather than typed into a
            table — should not carry a CTA that does nothing when pressed. The
            `ml-auto` moves to the Export button below so the right cluster
            still sits right. */}
        {createMenu && createMenu.length > 0 ? (
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button
                size="xs"
                className={cn(
                  "mb-3 self-end rounded-[4px]",
                  !segments?.length && "ml-auto"
                )}
              >
                <Plus />
                {ctaLabel}
                <ChevronDown />
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end" className="w-80">
              {createMenu.map((o, i) =>
                o.choices?.length ? (
                  <React.Fragment key={o.key}>
                    {i > 0 && <DropdownMenuSeparator />}
                    {/* The group's own name is a HEADING, not a button — the
                        entries below it are the choice. Plain entries, no
                        radios (Pavan, 2026-10-05): each one STARTS an order,
                        so there is no selection for a dot to hold. */}
                    <DropdownMenuLabel className="flex flex-col items-start gap-0.5 py-2 font-normal">
                      <span className="text-sm font-medium text-foreground">
                        {o.label}
                      </span>
                      {o.detail && (
                        <span className="text-xs text-muted-foreground">{o.detail}</span>
                      )}
                    </DropdownMenuLabel>
                    {o.choices.map((c) => (
                      <DropdownMenuItem
                        key={c.key}
                        className="flex-col items-start gap-0.5 py-2"
                        onSelect={() => onCreateSelect?.(c.key)}
                      >
                        <span className="text-sm text-foreground">{c.label}</span>
                        {c.detail && (
                          <span className="text-xs text-muted-foreground">
                            {c.detail}
                          </span>
                        )}
                      </DropdownMenuItem>
                    ))}
                  </React.Fragment>
                ) : (
                  <DropdownMenuItem
                    key={o.key}
                    className="flex-col items-start gap-0.5 py-2"
                    onSelect={() => onCreateSelect?.(o.key)}
                  >
                    <span className="text-sm font-medium text-foreground">{o.label}</span>
                    {o.detail && (
                      <span className="text-xs text-muted-foreground">{o.detail}</span>
                    )}
                  </DropdownMenuItem>
                )
              )}
            </DropdownMenuContent>
          </DropdownMenu>
        ) : (
          onCreateOrder && (
            <Button
              size="xs"
              className={cn(
                "mb-3 self-end rounded-[4px]",
                !segments?.length && "ml-auto"
              )}
              onClick={onCreateOrder}
            >
              <Plus />
              {ctaLabel}
            </Button>
          )
        )}

        {/*
          Export, moved down from the page header so both actions for this list
          sit together. `icon-xs` (24px) matches the CTA's height, and the same
          self-end/mb-3 puts them on one baseline.

          It is the rightmost item, so it carries the `mr-1` that keeps this row
          aligned with the toolbar below: the row cancels the content layer's
          16px inset with -mx-4 and re-pads at px-3, so without the extra 4px the
          trailing control would sit proud of every toolbar control under it.
        */}
        <Tooltip>
          <TooltipTrigger asChild>
            <Button
              variant="ghost"
              size="icon-xs"
              aria-label="Export"
              onClick={onExport}
              className={cn(
                "mr-1 mb-3 self-end",
                // Takes over pushing the right cluster right when there is no CTA.
                onCreateOrder || createMenu || segments?.length ? "ml-1.5" : "ml-auto"
              )}
            >
              <Upload />
            </Button>
          </TooltipTrigger>
          <TooltipContent>Export</TooltipContent>
        </Tooltip>
      </div>

      <Dialog open={dialog !== null} onOpenChange={(o) => !o && setDialog(null)}>
        <DialogContent className="sm:max-w-sm">
          <DialogHeader>
            <DialogTitle>
              {dialog?.mode === "rename" ? "Rename view" : "Save current view"}
            </DialogTitle>
          </DialogHeader>
          <div className="grid gap-2">
            <Label htmlFor="fuel-view-name">View name</Label>
            <Input
              id="fuel-view-name"
              autoFocus
              value={dialog?.name ?? ""}
              onChange={(e) =>
                setDialog((d) => (d ? { ...d, name: e.target.value } : d))
              }
              onKeyDown={(e) => {
                if (e.key === "Enter") submit();
                /* TAKE THE SUGGESTION to add to it. */
                if ((e.key === "ArrowRight" || e.key === "Tab") && !dialog?.name && dialog?.suggestion) {
                  e.preventDefault();
                  setDialog((d) => (d ? { ...d, name: `${d.suggestion} ` } : d));
                }
              }}
              placeholder={(dialog?.mode === "new" && dialog.suggestion) || "e.g. Unassigned today"}
            />
          </div>
          <DialogFooter>
            <DialogClose asChild>
              <Button variant="outline">Cancel</Button>
            </DialogClose>
            <Button
              onClick={submit}
              disabled={!dialog?.name.trim() && !(dialog?.mode === "new" && dialog.suggestion)}
            >
              {dialog?.mode === "rename" ? "Rename" : "Save view"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
}

import * as React from "react";
import { History, ListFilter, Search } from "lucide-react";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import { Input } from "@/components/ui/input";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import {
  clearActiveFilters,
  groupIds,
  listKeyOf,
  readHistory,
  recordHistory,
  setActiveFilters,
  type HistoryEntry,
} from "./filterMemory";

/**
 * Faceted filter panel, generic over its facets.
 *
 * Structure is the DS panel's (Figma "Action Bar Unit · Filter interactions",
 * 27665:14074): facet side menu + options pane + Clear All / Apply footer, same
 * sizes and classes Fuel Orders proved.
 *
 * SEARCH IS PER-FACET, and that is the rule this carries forward: a facet gets a
 * search field when its list cannot be taken in at once, and does not when it is
 * short enough to scan. `searchable` is an explicit flag rather than a length
 * threshold, so a facet cannot silently gain or lose the control as its options
 * change.
 *
 * DS FOLLOW-UP: this is the parameterised `tables-layout/FilterPanel` that
 * `docs/handoff-ds-adoption-2.md` Task 5 asks for. When the DS version takes
 * facets as props, this file deletes itself.
 */
/**
 * An option is either a bare value, or a value with a second line under it —
 * a ship-to needs its address to be told apart from a similarly-named site, and
 * the checkbox label alone cannot carry that.
 */
export type ListOption = string | { value: string; description: string };

const optionValue = (o: ListOption) => (typeof o === "string" ? o : o.value);
const optionDescription = (o: ListOption) =>
  typeof o === "string" ? undefined : o.description;

export interface ListFacetSection {
  title: string;
  options: ListOption[];
}

export interface ListFacet {
  key: string;
  label: string;
  /** Flat option list. Omit when the facet uses `sections`. */
  options?: ListOption[];
  /**
   * A facet that asks the SAME question at several grains — ship-to name, ZIP,
   * state are all "which address" — puts them in one pane under sub-headings
   * rather than eating three rows of the facet menu. Selections across sections
   * are independent, and the facet's count is their total.
   */
  sections?: ListFacetSection[];
  /** Give the options pane a search field. Off for lists you can take in whole. */
  searchable?: boolean;
}

/** Every option a facet holds, flat — for counting and for search. */
const facetOptions = (f: ListFacet): string[] =>
  (f.options ?? f.sections?.flatMap((sec) => sec.options) ?? []).map(optionValue);

export function ListFilters({
  facets,
  value,
  onApply,
  fullWidth = false,
  countFor,
  historyKey,
}: {
  facets: ListFacet[];
  /** Which list's RECENT HISTORY this is — defaults to the facets it has. */
  historyKey?: string;
  /** Stretch the trigger to its container — for a row of its own, in a sheet. */
  fullWidth?: boolean;
  /**
   * What is actually applied, when the caller keeps it.
   *
   * The panel STAGES changes — nothing narrows until Apply — so it holds its
   * own working copy, and that copy has to be reset to the truth each time the
   * panel opens or it will re-apply a tick the reader took off somewhere else.
   * Somewhere else is the chip shelf: take a chip off, open the panel, and
   * without this the checkbox would still be on.
   */
  value?: ReadonlySet<string>;
  /**
   * Fires on Apply and on Clear All with the selected `facetKey:option` ids.
   *
   * Left out, the panel is a composition demo — it shows the interaction and
   * narrows nothing, which is what every screen got before Order Types moved
   * in here from a tab row. A facet that REPLACES working behaviour has to be
   * wired, so the caller passes this and applies what it can.
   */
  onApply?: (selected: ReadonlySet<string>) => void;
  /**
   * HOW MANY ROWS THE TICKS WOULD LEAVE (Pavan, 2026-10-05) — shown on the
   * footer's left as the reader ticks, before Apply. The screen answers it
   * with the same narrowing it applies, everything else on screen included
   * (search, column boxes, scope). Left out, the footer has no count.
   */
  countFor?: (selected: ReadonlySet<string>) => number;
}) {
  const [open, setOpen] = React.useState(false);
  const [checked, setChecked] = React.useState<Set<string>>(new Set());
  /* RECENT HISTORY (Pavan, 2026-10-21) — the toolbar's panel only; the
     export sheet's copy applies as it goes and keeps none. */
  const list = historyKey ?? listKeyOf(facets);
  const [history, setHistory] = React.useState<HistoryEntry[]>([]);
  /* THE VIEW ROW NAMES A VIEW FROM WHAT IS ON — see `filterMemory`. */
  React.useEffect(() => {
    if (fullWidth) return;
    setActiveFilters(facets, value ?? checked);
    return () => clearActiveFilters(facets);
  });

  const applied = value ? value.size : checked.size;

  const toggle = (key: string) =>
    setChecked((prev) => {
      const next = new Set(prev);
      if (next.has(key)) next.delete(key);
      else next.add(key);
      return next;
    });

  return (
    <Popover
      open={open}
      onOpenChange={(next) => {
        if (next && value) setChecked(new Set(value));
        if (next && !fullWidth) setHistory(readHistory(list));
        setOpen(next);
      }}
    >
      {/* `asChild` slots onto exactly ONE child, so this note sits outside the
          trigger — as raw text inside it, React counted it as a second child and
          Radix threw "failed to slot onto its children".
          `bg-transparent` makes the button outline-only, like the search field
          beside it: the DS `outline` variant fills with `bg-background` (#efefeb
          light), the APP background, which is right when the button sits on it
          and wrong here on the white content layer, where it read as a filled
          grey block next to a transparent input. The stroke moves to
          `--input` so it matches the field beside it: the `outline` variant uses
          `--border` in light but ALREADY uses `--input` in dark, so light was the
          odd one out and the button read a shade lighter than the input. */}
      <PopoverTrigger asChild>
        <Button
          variant="outline"
          size="sm"
          className={cn(fullWidth && "h-8 w-full justify-start")}
        >
          <ListFilter />
          Filters
          {/* THE COUNT IS WHAT IS APPLIED, NOT WHAT IS TICKED. The panel's own
              ticks are a draft until Apply, and the button is read with the
              panel shut — a number that moved as you ticked would be counting
              a narrowing that has not happened. It also has to follow a chip
              being taken off outside the panel. Falls back to the ticks only
              where the caller does not keep the applied set. */}
          {applied > 0 && (
            <span className="ml-1 rounded-full bg-accent px-1.5 text-xs tabular-nums">
              {applied}
            </span>
          )}
        </Button>
      </PopoverTrigger>
      <PopoverContent align="start" className="w-[600px] overflow-hidden p-0">
        <ListFilterPanel
          facets={facets}
          checked={checked}
          onToggle={toggle}
          menuWidth={200}
          height={264}
          history={fullWidth ? undefined : history}
          onPickHistory={(ids) => setChecked(new Set(ids))}
        />

        {/* THE COUNT ON THE LEFT, BOTH ACTS ON THE RIGHT (Pavan,
            2026-10-05). The number is what Apply would show — read before
            committing to it. Clear All sits beside Apply as its quieter
            sibling, not across the bar from it. */}
        <div className="flex h-16 items-center justify-between gap-3 border-t border-border px-4">
          <span className="text-sm tabular-nums text-muted-foreground" aria-live="polite">
            {countFor && (
              <>
                <span className="font-medium text-foreground">
                  {countFor(checked).toLocaleString()}
                </span>{" "}
                {countFor(checked) === 1 ? "result" : "results"}
              </>
            )}
          </span>
          <div className="flex items-center gap-2">
            <Button
              variant="ghost"
              size="sm"
              onClick={() => {
                const empty = new Set<string>();
                setChecked(empty);
                onApply?.(empty);
              }}
            >
              Clear All
            </Button>
            <Button
              size="sm"
              onClick={() => {
                if (!fullWidth) recordHistory(list, checked);
                onApply?.(checked);
                setOpen(false);
              }}
            >
              Apply Filters
            </Button>
          </div>
        </div>
      </PopoverContent>
    </Popover>
  );
}

/**
 * The panel's BODY — facet menu, options pane — with no chrome of its own.
 *
 * Split out so the same two panes can be a popover on a toolbar and a plain
 * block inside a sheet. The export sheet takes the second form: a panel that
 * opens another floating panel on top of itself is two layers deep for one
 * question, and the reader loses sight of the count they are deciding about.
 *
 * IT DOES NOT OWN WHAT IS TICKED. The popover stages its ticks until Apply and
 * the sheet applies them as they happen, and that difference belongs to the
 * caller — this renders a set and reports toggles.
 */
export function ListFilterPanel({
  facets,
  checked,
  onToggle,
  menuWidth = 200,
  height,
  className,
  history,
  onPickHistory,
}: {
  facets: ListFacet[];
  /** RECENT HISTORY — filter sets applied in the last 24 hours. The menu
      leads with it only when there are some. */
  history?: HistoryEntry[];
  onPickHistory?: (ids: string[]) => void;
  /** Ticked ids, as `facetKey:option`. */
  checked: ReadonlySet<string>;
  onToggle: (id: string) => void;
  /** The facet column's width. Narrower inside a sheet than in the popover. */
  menuWidth?: number;
  /**
   * Fix the panes' height and let them scroll inside it.
   *
   * FOR A POPOVER, which cannot grow past the window it floats in. Left out —
   * the sheet — the panel is as tall as its longest pane and nothing scrolls:
   * a facet list in a column with room to spare does not need a viewport of its
   * own, and a scroller hides how much there is to read.
   */
  height?: number;
  className?: string;
}) {
  const [facetKey, setFacetKey] = React.useState(facets[0]?.key ?? "");
  const [query, setQuery] = React.useState("");

  const HISTORY = "__history";
  const showHistory = facetKey === HISTORY && Boolean(history?.length);
  const facet = facets.find((f) => f.key === facetKey) ?? facets[0];

  const q = query.toLowerCase();
  /* Search matches the description as well as the value: on a ship-to facet the
     address IS what people search by — a city or a state, not the site name. */
  const match = (o: ListOption) =>
    optionValue(o).toLowerCase().includes(q) ||
    (optionDescription(o) ?? "").toLowerCase().includes(q);
  /** One shape for both facet kinds: an unlabelled section is a flat list. */
  const sections: ListFacetSection[] = facet
    ? (facet.sections ?? [{ title: "", options: facet.options ?? [] }]).map(
        (sec) => ({ ...sec, options: sec.options.filter(match) })
      )
    : [];
  const hits = sections.reduce((n, sec) => n + sec.options.length, 0);

  const scrolls = height !== undefined;

  return (
    <div className={cn("flex", className)} style={height ? { height } : undefined}>
      <div
        className={cn(
          "flex shrink-0 flex-col gap-1 border-r border-border p-2",
          scrolls && "overflow-auto"
        )}
        style={{ width: menuWidth }}
      >
        {history && history.length > 0 && (
          <button
            type="button"
            onClick={() => {
              setFacetKey(HISTORY);
              setQuery("");
            }}
            className={cn(
              "flex h-8 shrink-0 items-center gap-2 rounded-md px-2 text-left text-sm outline-none transition-colors hover:bg-accent/60 focus-visible:ring-2 focus-visible:ring-ring/50",
              showHistory ? "bg-accent text-accent-foreground" : "text-muted-foreground hover:text-foreground"
            )}
          >
            <History className="size-4 shrink-0" />
            <span className="flex-1 truncate">Recent history</span>
            <span className="text-xs tabular-nums text-muted-foreground">{history.length}</span>
          </button>
        )}
        {facets.map((f) => {
          const n = facetOptions(f).filter((o) =>
            checked.has(`${f.key}:${o}`)
          ).length;
          return (
            <button
              key={f.key}
              type="button"
              onClick={() => {
                setFacetKey(f.key);
                setQuery("");
              }}
              className={cn(
                "flex h-8 shrink-0 items-center gap-2 rounded-md px-2 text-left text-sm outline-none transition-colors hover:bg-accent/60 focus-visible:ring-2 focus-visible:ring-ring/50",
                facetKey === f.key
                  ? "bg-accent text-accent-foreground"
                  : "text-muted-foreground hover:text-foreground"
              )}
            >
              <span className="flex-1 truncate">{f.label}</span>
              {n > 0 && (
                <span className="text-xs tabular-nums text-muted-foreground">
                  {n}
                </span>
              )}
            </button>
          );
        })}
      </div>

      {showHistory ? (
        /* EACH SET AS IT WAS APPLIED, by category — a press puts its ticks
           back; Apply applies them. */
        <div className={cn("flex min-w-0 flex-1 flex-col gap-1.5 p-2", scrolls && "min-h-0 overflow-auto")}>
          {history!.map((e) => {
            const on = e.ids.length === checked.size && e.ids.every((id) => checked.has(id));
            return (
              <button
                key={e.at}
                type="button"
                aria-pressed={on}
                onClick={() => onPickHistory?.(e.ids)}
                className={cn(
                  "flex flex-col gap-1 rounded-md border px-3 py-2 text-left outline-none transition-colors hover:bg-fp-row-hover focus-visible:ring-2 focus-visible:ring-ring/50",
                  on ? "border-selected-border bg-selected" : "border-border"
                )}
              >
                {groupIds(facets, e.ids).map((g) => (
                  <span key={g.key} className="flex min-w-0 gap-1.5 text-sm">
                    <span className="shrink-0 text-muted-foreground">{g.label}</span>
                    <span className="truncate text-foreground">{g.values.join(", ")}</span>
                  </span>
                ))}
                <span className="text-xs text-muted-foreground">{ago(e.at)}</span>
              </button>
            );
          })}
        </div>
      ) : (
      <div className="flex min-w-0 flex-1 flex-col">
        {facet?.searchable && (
          <div className="p-2">
            <div className="relative">
              <Search className="pointer-events-none absolute top-1/2 left-2.5 size-4 -translate-y-1/2 text-muted-foreground" />
              <Input
                value={query}
                onChange={(e) => setQuery(e.target.value)}
                placeholder={`Search ${facet.label.toLowerCase()}…`}
                className="h-8 pl-8"
              />
            </div>
          </div>
        )}
        <div
          className={cn(
            "flex-1 px-2 pb-2",
            scrolls && "min-h-0 overflow-auto",
            !facet?.searchable && "pt-2"
          )}
        >
          {sections.map((sec) =>
            sec.options.length === 0 ? null : (
              <div key={sec.title || "flat"} className="flex flex-col">
                {sec.title && (
                  <p className="px-0.5 pt-2 pb-1 text-xs font-medium tracking-wide text-muted-foreground uppercase">
                    {sec.title}
                  </p>
                )}
                {sec.options.map((opt) => {
                  const value = optionValue(opt);
                  const description = optionDescription(opt);
                  const id = `${facet.key}:${value}`;
                  return (
                    <label
                      key={id}
                      className="flex min-h-8 cursor-pointer items-start gap-2 py-1"
                    >
                      <Checkbox
                        checked={checked.has(id)}
                        onCheckedChange={() => onToggle(id)}
                        aria-label={value}
                        /* Nudged down so it centres on the FIRST line, not on
                           the two-line block. */
                        className="mt-0.5"
                      />
                      <span className="flex min-w-0 flex-col">
                        <span className="text-sm">{value}</span>
                        {description && (
                          <span className="text-xs text-muted-foreground">
                            {description}
                          </span>
                        )}
                      </span>
                    </label>
                  );
                })}
              </div>
            )
          )}
          {hits === 0 && (
            <p className="px-2 py-1 text-sm text-muted-foreground">No matches.</p>
          )}
        </div>
      </div>
      )}
    </div>
  );
}

/** "Just now", "12 min ago", "3 h ago" — inside the 24 hours history keeps. */
function ago(at: number) {
  const min = Math.round((Date.now() - at) / 60_000);
  if (min < 1) return "Just now";
  if (min < 60) return `${min} min ago`;
  return `${Math.round(min / 60)} h ago`;
}

import type { ListFacet, ListOption } from "./ListFilters";

/*
  WHAT A LIST'S FILTERS REMEMBER (Pavan, 2026-10-21):

    RECENT HISTORY   every set of filters applied in the last 24 hours, per
                     list, newest first — the Filters panel offers them back
                     under "Recent history" (only when there are any).
    SUGGESTED NAME   what "Save view" proposes, read off the filters that are
                     on: the line of service first, then the business, then
                     the rest in panel order — "Transport · Priya Raman".

  The toolbar's Filters control registers the list's facets and applied ticks
  here as it renders, so the view row on the same screen can name a view
  without every screen wiring the two together.
*/

const DAY = 24 * 3_600_000;
const MAX_ENTRIES = 8;

export interface HistoryEntry {
  at: number;
  ids: string[];
}

const storeKey = (list: string) => `fp-filter-history:${list}`;

/** The list's applied filter sets from the last 24 hours, newest first. */
export function readHistory(list: string): HistoryEntry[] {
  try {
    const raw = window.localStorage.getItem(storeKey(list));
    const all = raw ? (JSON.parse(raw) as HistoryEntry[]) : [];
    return all.filter((e) => Date.now() - e.at < DAY && e.ids.length > 0);
  } catch {
    return [];
  }
}

/** Keep an applied set — the same set again moves to the top, not twice. */
export function recordHistory(list: string, ids: Iterable<string>) {
  const sorted = [...ids].sort();
  if (sorted.length === 0) return;
  const key = sorted.join("|");
  const next = [{ at: Date.now(), ids: sorted }, ...readHistory(list).filter((e) => e.ids.join("|") !== key)].slice(
    0,
    MAX_ENTRIES
  );
  try {
    window.localStorage.setItem(storeKey(list), JSON.stringify(next));
  } catch {
    /* No storage — the history is simply not kept. */
  }
}

/** A list's identity for its history: which facets it has. */
export const listKeyOf = (facets: ListFacet[]) => facets.map((f) => f.key).join(",");

/* ------------------------------------------------- the active filters --- */

let active: { facets: ListFacet[]; ids: ReadonlySet<string> } | null = null;
export const setActiveFilters = (facets: ListFacet[], ids: ReadonlySet<string>) => {
  active = { facets, ids };
};
export const clearActiveFilters = (facets: ListFacet[]) => {
  if (active?.facets === facets) active = null;
};

/** The applied ticks, grouped by facet in panel order: label and values. */
export function groupIds(facets: ListFacet[], ids: Iterable<string>) {
  const set = new Set(ids);
  const value = (o: ListOption) => (typeof o === "string" ? o : o.value);
  return facets
    .map((f) => ({
      key: f.key,
      label: f.label,
      values: (f.options ?? f.sections?.flatMap((s) => s.options) ?? []).map(value).filter((v) => set.has(`${f.key}:${v}`)),
    }))
    .filter((g) => g.values.length > 0);
}

/* WHICH FACETS NAME A VIEW FIRST — the line of service, then the business. */
const LEADS = [["serviceLine", "line", "orderKind", "los"], ["business"]];

/**
 * THE SUGGESTED VIEW NAME (Pavan, 2026-10-21). From the filters on:
 *   - the line of service, then the business, then the other facets in panel
 *     order — a business stands in for its line ("Transport", not
 *     "Fuel · Transport");
 *   - a facet with one value gives that value, two give "A & B", more give
 *     the count and the facet's name ("3 Status");
 *   - at most three parts, joined with " · ".
 * Empty when nothing is filtered.
 */
export function suggestViewName(): string {
  if (!active || active.ids.size === 0) return "";
  const groups = groupIds(active.facets, active.ids);
  const rank = (key: string) => {
    const i = LEADS.findIndex((keys) => keys.includes(key));
    return i < 0 ? LEADS.length : i;
  };
  /* A BUSINESS SAYS ITS LINE — Transport is fuel — so the line drops. */
  const hasBusiness = groups.some((g) => LEADS[1].includes(g.key));
  const ordered = groups
    .filter((g) => !(hasBusiness && LEADS[0].includes(g.key)))
    .map((g, i) => ({ g, i }))
    .sort((a, b) => rank(a.g.key) - rank(b.g.key) || a.i - b.i)
    .map(({ g }) => g);
  return ordered
    .slice(0, 3)
    .map((g) =>
      g.values.length === 1 ? g.values[0] : g.values.length === 2 ? `${g.values[0]} & ${g.values[1]}` : `${g.values.length} ${g.label}`
    )
    .join(" · ");
}

import * as React from "react";

/**
 * Saved-view state for a list screen, generic over what a view captures.
 *
 * The interaction is the DS's finalized one (`data-action-control/
 * DataActionControl.tsx`): a Default tab plus saved tabs, a dirty dot when the
 * live state has drifted from the active view, and rename / update / delete on
 * each saved tab. Fuel Orders proved it; this hook is what lets Asset Orders and
 * Customers have the same thing without a third and fourth copy of the state.
 *
 * `keyOf` exists so drift detection cannot be fooled by key order — each screen
 * serialises its own state deterministically.
 */
/*
  A LIST REMEMBERS WHERE IT WAS LEFT (Pavan, 2026-10-09). Leaving a page and
  coming back finds the same filters, search, sort and view — still dirty if
  they were, still savable as a view, still clearable — until Clear all (or
  the view's own reset) takes them off. Kept for the session in memory, one
  entry per list (`storageKey`); a page reload starts clean.
*/
type Kept<S> = {
  views: { id: string; name: string; state: S }[];
  activeId: string | null;
  working: Record<string, S>;
  current: S;
  seq: number;
};
const KEPT = new Map<string, Kept<unknown>>();

export function useSavedViews<S>({
  current,
  defaultState,
  keyOf,
  apply,
  storageKey,
  restore = true,
}: {
  current: S;
  defaultState: S;
  keyOf: (s: S) => string;
  apply: (s: S) => void;
  /** Remembers this list across leaving and coming back — see `KEPT`. */
  storageKey?: string;
  /** False when the visit arrives with its own narrowing (a dashboard drill),
      which then wins over what was left. */
  restore?: boolean;
}) {
  const kept = storageKey ? (KEPT.get(storageKey) as Kept<S> | undefined) : undefined;
  const [views, setViews] = React.useState<{ id: string; name: string; state: S }[]>(
    () => kept?.views ?? []
  );
  const [activeId, setActiveId] = React.useState<string | null>(() => kept?.activeId ?? null);
  const seq = React.useRef(kept?.seq ?? 0);
  /* ON RETURN, PUT THE LIST BACK as it was left — once, after mount. */
  React.useEffect(() => {
    if (kept && restore && keyOf(kept.current) !== keyOf(current)) apply(kept.current);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  /* EACH VIEW KEEPS ITS UNSAVED CHANGES (Pavan, 2026-09-24) — leaving a view
     and coming back finds it as it was left, dirty dot and all. Keyed by view
     id, "" for Default. Saving or updating the view clears its entry. */
  const working = React.useRef<Record<string, S>>(kept?.working ?? {});
  /* KEEP EVERYTHING ON EVERY CHANGE, so leaving at any moment loses nothing. */
  React.useEffect(() => {
    if (!storageKey) return;
    KEPT.set(storageKey, {
      views,
      activeId,
      working: working.current,
      current,
      seq: seq.current,
    } as Kept<unknown>);
  });
  const DEFAULT_KEY = "";

  const activeView = views.find((v) => v.id === activeId) ?? null;
  const dirty = keyOf(current) !== keyOf(activeView ? activeView.state : defaultState);

  /** Park what is on screen against the view being left. */
  const park = () => {
    const key = activeId ?? DEFAULT_KEY;
    if (dirty) working.current[key] = current;
    else delete working.current[key];
  };

  return {
    views,
    activeId,
    dirty,
    /* PRESSING THE TAB YOU ARE ON puts it back to its saved state — the one
       way to drop what was changed. Pressing another tab keeps both. */
    onApply: (id: string) => {
      const v = views.find((x) => x.id === id);
      if (!v) return;
      if (id === activeId) {
        delete working.current[id];
        apply(v.state);
        return;
      }
      park();
      apply(working.current[id] ?? v.state);
      setActiveId(id);
    },
    onResetToDefault: () => {
      if (activeId === null) {
        delete working.current[DEFAULT_KEY];
        apply(defaultState);
        return;
      }
      park();
      apply(working.current[DEFAULT_KEY] ?? defaultState);
      setActiveId(null);
    },
    onCreate: (name: string) => {
      const id = `v-${++seq.current}`;
      /* The changes move INTO the new view, so the view left is clean again. */
      delete working.current[activeId ?? DEFAULT_KEY];
      setViews((prev) => [...prev, { id, name, state: current }]);
      setActiveId(id);
    },
    onRename: (id: string, name: string) =>
      setViews((prev) => prev.map((v) => (v.id === id ? { ...v, name } : v))),
    onUpdate: (id: string) => {
      delete working.current[id];
      setViews((prev) =>
        prev.map((v) => (v.id === id ? { ...v, state: current } : v))
      );
    },
    onDelete: (id: string) => {
      delete working.current[id];
      setViews((prev) => prev.filter((v) => v.id !== id));
      if (activeId === id) setActiveId(null);
    },
  };
}

import * as React from "react"
import { cva, type VariantProps } from "class-variance-authority"
import { Slot } from "radix-ui"

import { cn } from "@/lib/utils"

const buttonVariants = cva(
  "inline-flex shrink-0 items-center justify-center gap-2 rounded-md text-sm font-medium whitespace-nowrap transition-all outline-none focus-visible:border-ring focus-visible:ring-2 focus-visible:ring-ring/50 disabled:pointer-events-none disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
  {
    variants: {
      variant: {
        default: "bg-primary text-primary-foreground hover:bg-primary/90",
        destructive:
          "bg-destructive text-destructive-foreground hover:bg-destructive/90 focus-visible:ring-destructive/20 dark:bg-destructive/60 dark:focus-visible:ring-destructive/40",
        // `bg-transparent`, NOT `bg-background`. `--background` is the APP
        // background (#efefeb light), which is right only when the button sits
        // ON it — and wrong on the white content layer, where every toolbar and
        // every table row puts outline buttons. Measured on one gallery route
        // before this change: 51 controls filled #efefeb on a #ffffff layer.
        //
        // Transparent is neutral-or-better everywhere, which is why this belongs
        // in the variant rather than at call sites: on the app background it
        // composites to the identical colour, on the content layer it renders
        // #ffffff, and on a card it inherits the card instead of fighting it.
        //
        // The stroke is `--input` in BOTH themes now. The variant already used
        // `--input` in dark; light was the odd one out at `--border` (#cdd4de vs
        // the field's #abb3c2), so an outline button read a shade lighter than
        // the input beside it in every toolbar.
        outline:
          "border border-input bg-transparent hover:bg-accent hover:text-accent-foreground dark:bg-fp-field-fill dark:hover:bg-fp-field-fill-hover",
        secondary:
          "bg-secondary text-secondary-foreground hover:bg-secondary/80",
        // The affirmative counterpart to `destructive`: a filled button for the
        // one action that MOVES SOMETHING FORWARD where an outline would be
        // read as optional. Same green the status family uses, with its own
        // foreground — see the note on `--status-success-foreground`.
        success:
          "bg-status-success text-status-success-foreground hover:bg-status-success/90 focus-visible:ring-status-success/30",
        ghost:
          "hover:bg-accent hover:text-accent-foreground dark:hover:bg-accent/50",
        link: "text-primary underline-offset-4 hover:underline",
      },
      size: {
        default: "h-9 px-4 py-2 has-[>svg]:px-3",
        xs: "h-6 gap-1 rounded-md px-2 text-xs has-[>svg]:px-1.5 [&_svg:not([class*='size-'])]:size-3",
        sm: "h-8 gap-1.5 rounded-md px-3 has-[>svg]:px-2.5",
        lg: "h-10 rounded-md px-6 has-[>svg]:px-4",
        icon: "size-9",
        "icon-xs": "size-6 rounded-md [&_svg:not([class*='size-'])]:size-3",
        "icon-sm": "size-8",
        "icon-lg": "size-10",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  }
)

function Button({
  className,
  variant = "default",
  size = "default",
  asChild = false,
  ...props
}: React.ComponentProps<"button"> &
  VariantProps<typeof buttonVariants> & {
    asChild?: boolean
  }) {
  const Comp = asChild ? Slot.Root : "button"

  return (
    <Comp
      data-slot="button"
      data-variant={variant}
      data-size={size}
      className={cn(buttonVariants({ variant, size, className }))}
      {...props}
    />
  )
}

export { Button, buttonVariants }

